<dialog class="media-picker" id="media-picker" aria-labelledby="media-picker-title" data-loading="<?= t('Loading images…') ?>" data-empty="<?= t('No matching images. Upload one or try another search.') ?>" data-selected="<?= t('Image selected. Save the form to apply it.') ?>" data-load-preview="<?= t('Select to preview this large image') ?>" data-preview-label="<?= t('Select an image to preview') ?>">
<div class="dialog-heading"><div><h2 id="media-picker-title"><?= t('Choose an existing image') ?></h2><p class="hint"><?= t('Only public images appear here. Choosing an image does not create another upload.') ?></p></div><button type="button" class="icon-button" data-close-dialog aria-label="<?= t('Close') ?>"><?= icon('close') ?></button></div>
<form class="media-picker-search" data-media-search><label class="sr-only" for="media-search-query"><?= t('Search images by filename') ?></label><input class="input" type="search" id="media-search-query" maxlength="100" placeholder="<?= t('Search images by filename') ?>"><label class="sr-only" for="media-picker-scope"><?= t('Image source') ?></label><select class="input" id="media-picker-scope"><option value="mine"><?= t('My images') ?></option><?php if(in_array($me['role'],['admin','editor'],true)): ?><option value="all"><?= t('All public images') ?></option><?php endif ?></select><button type="submit" class="btn secondary"><?= icon('search') ?><?= t('Search') ?></button></form>
<p class="hint" role="status" aria-live="polite" data-media-status></p><div class="media-picker-body"><div><div class="media-picker-grid" data-media-items></div><nav class="media-picker-pages" aria-label="<?= t('Image pages') ?>"><button type="button" class="btn secondary small" data-media-previous><?= t('Previous') ?></button><button type="button" class="btn secondary small" data-media-next><?= t('Next') ?></button></nav></div><aside class="media-picker-preview"><div class="media-picker-stage"><span data-media-placeholder><?= icon('anime-gallery') ?></span><img data-media-preview alt="" hidden><p class="hint" data-media-preview-error hidden><?= t('The image could not be loaded.') ?></p></div><strong data-media-name><?= t('Select an image to preview') ?></strong><p class="hint" data-media-info></p><button type="button" class="btn full" data-media-confirm disabled><?= t('Use this image') ?></button></aside></div>
</dialog>
